// ============ NEV SETTINGS (DEMO) ============  edit these, nothing else
// One click runs the whole night. Everything comes to YOU, and nothing is bought.
return [{ json: {
  DEMO: true,
  ME: 'Mate',
  EX_NAME: 'Jess',
  TELEGRAM_CHAT_ID: 'YOUR_TELEGRAM_CHAT_ID',
  TIMEZONE: 'Australia/Perth',
  HOME: { lat: -31.9523, lng: 115.8613 },
  BIG_NIGHT_STEPS: 6000,                   // steps between midnight and 2am that mean "a big one"
  FOOD: ['Maccas Big Brekkie Burger'],
  CHEMIST: ['Blue Powerade', 'Hydralyte', 'Panadol'],
  SAUNA_OVERRIDE: '',                      // type a venue here to use it instead of the closest one on the map
  SAUNA_TIME: '15:00',
  MODEL: 'claude-sonnet-5-5',
} }];

// A big Saturday night. Simulated: the demo never touches your bank or your watch.
const S = $('Nev settings').first().json;
return [{ json: {
  tabs: [
    { at: '22:41', merchant: 'The Rusty Anchor Bar', amount: 16 },
    { at: '23:37', merchant: 'The Rusty Anchor Bar', amount: 32 },
    { at: '00:12', merchant: 'The Rusty Anchor Bar', amount: 48 },
    { at: '00:44', merchant: 'Sportsbet', amount: 50 },
    { at: '01:03', merchant: 'The Rusty Anchor Bar', amount: 64 },
    { at: '01:21', merchant: 'Sportsbet', amount: 100 },
    { at: '01:58', merchant: 'Kebab Kingdom', amount: 22.5 },
    { at: '02:16', merchant: 'Uber Trip', amount: 38.4 },
  ],
  steps: 9412,
  exAttempts: 3,
} }];

const KIND_RULES = [
  ['sportsbet', /sportsbet|ladbrokes|tab\b|neds|bet365|betr\b|pointsbet|unibet/i],
  ['kebab', /kebab|hsp|souvlaki|gyro|pizza|maccas|mcdonald|hungry jack|kfc|red rooster|chicken treat|takeaway/i],
  ['uber', /uber|didi|ola\b|taxi|13cabs/i],
  ['bar', /\bbar\b|pub\b|tavern|hotel|brewery|brewing|nightclub|club\b|lounge|arms\b|inn\b|anchor/i],
];
const kindOf = (m, upCategory) => {
  if (upCategory === 'pubs-and-bars') return 'bar';
  for (const [k, re] of KIND_RULES) if (re.test(m || '')) return k;
  return 'unknown';
};

// Is this a big one? A bar tap after midnight AND a huge step count between 12 and 2am.
const S = $('Nev settings').first().json;
const n = $input.first().json;
const tabs = n.tabs.map(t => ({ ...t, kind: kindOf(t.merchant) }));
const afterMidnight = t => t.at < '06:00';
const sum = k => tabs.filter(t => t.kind === k).reduce((a, t) => a + t.amount, 0);
const firstBar = tabs.find(t => t.kind === 'bar' && afterMidnight(t));
return [{ json: { tabs, steps: n.steps, exAttempts: n.exAttempts, firstBar,
  beers: sum('bar'), kebabs: sum('kebab'), sportsbet: sum('sportsbet'), ubers: sum('uber'),
  total: tabs.reduce((a, t) => a + t.amount, 0),
  bigOne: !!firstBar && n.steps >= S.BIG_NIGHT_STEPS } }];

// Simulated: the demo orders nothing. The full build sends two browser agents.
const S = $('Nev settings').first().json;
const msg = `💊 <b>You're awake. Care package ordered.</b>

🍔 ${S.FOOD.join(', ')}
🥤 ${S.CHEMIST.join(', ')}

🛵 At your door in about 25 minutes. Don't look at your phone yet.`;
return [{ json: { msg } }];

// Hands the night to Claude. It writes the report, the numbers stay ours.
const S = $('Nev settings').first().json;
const n = $('Read the night').first().json;
const money = v => '$' + Number(v).toFixed(2).replace(/\.00$/, '');
const facts = { steps_midnight_to_2am: n.steps, calls_or_texts_to_ex: n.exAttempts, ex_name: S.EX_NAME,
  beers: money(n.beers), kebabs_and_late_food: money(n.kebabs), sportsbet: money(n.sportsbet),
  ubers: money(n.ubers), total: money(n.total) };
const prompt = `You are Nev, a deadpan Australian nurse who looks after ${S.ME} the morning after a big night.
Write the damage report for Telegram from these facts only. Never invent a number or a detail.
${JSON.stringify(facts)}
Rules: start with one dry line. Then one short line each for the ex attempts, beers, kebabs, Sportsbet and the total, each with an emoji.
Under 70 words. Plain text only. Rip the bandaid off, but be on their side. No em dashes.`;
return [{ json: { body: { model: S.MODEL, max_tokens: 2000, messages: [{ role: 'user', content: prompt }] } } }];

const text = $input.first().json.content.map(c => c.text || '').join('').trim();
if (!text) throw new Error('Claude returned no text for the damage report');
return [{ json: { report: '🚨 <b>THE DAMAGE REPORT</b>\n\n' + text.replace(/[<>&]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' }[c])) } }];

const S = $('Nev settings').first().json;
const n = $('Read the night').first().json;
const prompt = `${S.ME} tried to contact their ex ${S.EX_NAME} ${n.exAttempts} times last night while drunk.
Write the text ${S.ME} sends this morning: a short, funny, face-saving apology that asks for nothing and doesn't reopen anything.
Under 25 words. No emojis. No em dashes. Output only the message.`;
return [{ json: { body: { model: S.MODEL, max_tokens: 1500, messages: [{ role: 'user', content: prompt }] } } }];

// The closest real sauna, from OpenStreetMap (Nominatim: free, no key).
const S = $('Nev settings').first().json;
const h = S.HOME;
const km = (a, b, c, d) => { const R = 6371, r = Math.PI / 180;
  const x = Math.sin((c - a) * r / 2) ** 2 + Math.cos(a * r) * Math.cos(c * r) * Math.sin((d - b) * r / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(x)); };
const list = $input.all().map(i => i.json).filter(s => s && s.lat)
  .map(s => ({ name: (s.name || s.display_name.split(',')[0]).trim(), km: km(h.lat, h.lng, +s.lat, +s.lon) }))
  .sort((a, b) => a.km - b.km);
if (S.SAUNA_OVERRIDE) return [{ json: { sauna: { name: S.SAUNA_OVERRIDE, km: null } } }];
return [{ json: { sauna: list[0] || { name: 'the closest sauna', km: null } } }];

// Simulated: Sportsbet and the sauna booking. The excuse and the sauna's name are real.
const S = $('Nev settings').first().json;
const excuse = $('Claude: the excuse').first().json.content.map(c => c.text || '').join('').trim();
if (!excuse) throw new Error('Claude returned no text for the excuse');
const sauna = $('Closest sauna').first().json.sauna;
const dist = sauna.km != null ? ` (${sauna.km.toFixed(1)} km away)` : '';
const msg = `🩺 <b>Damage controlled.</b>\n\n📱 Excuse sent to ${S.EX_NAME}\n🎰 Sportsbet deposit limit capped\n🧖 ${sauna.name}${dist}, booked for ${S.SAUNA_TIME}\n\nDrink your Hydralyte.`;
return [{ json: { excuse, msg } }];
